def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    units = int(supply / WATER_REQ)
    if units < 1:
        units = 1

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = 18.0
        if hp <= 2 or no_water_days >= 1:
            base = 45.0
        return float(max(0.0, min(budget, base)))

    est_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        b = None
        if prev:
            b = prev.get('bid')
        if b is None:
            b = opp.get('daily_salary', DAILY_SALARY) * 0.75

        if opp.get('no_water_days', 0) >= 1:
            b += 8.0
        if opp.get('hp', 10) <= 2:
            b += 12.0
        if opp.get('budget', 0) < b:
            b = opp.get('budget', 0)
        if b < 0:
            b = 0.0
        est_bids.append(float(b))

    est_bids.sort(reverse=True)
    target_index = int(units - 1)
    if target_index < 0:
        target_index = 0
    if target_index >= len(est_bids):
        target_index = int(len(est_bids) - 1)

    if len(est_bids) > 0:
        clear_est = est_bids[int(target_index)]
        top_est = est_bids[0]
    else:
        clear_est = DAILY_SALARY * 0.6
        top_est = clear_est

    if units == 1:
        bid = clear_est + 2.0
        if top_est > 120:
            bid = min(bid, 92.0)
        if hp <= 2 or no_water_days >= 1:
            bid = max(bid, min(budget, clear_est + 8.0, 110.0))
        elif hp >= 7 and no_water_days == 0:
            bid = min(bid, 72.0)
    else:
        bid = clear_est + 1.5
        if len(est_bids) >= 2:
            second_idx = int(min(len(est_bids) - 1, units))
            next_est = est_bids[int(second_idx)]
            if clear_est - next_est > 18:
                bid = max(next_est + 2.0, bid - 8.0)
        if hp >= 7 and no_water_days == 0:
            bid -= 6.0
        if hp <= 3:
            bid += 10.0
        if no_water_days >= 1:
            bid += 12.0

    if hp <= 2:
        bid = max(bid, 85.0)
    elif hp <= 4:
        bid = max(bid, 62.0)

    if budget < 50:
        bid = min(bid, budget)
    else:
        reserve = 0.0
        if hp >= 6 and no_water_days == 0:
            reserve = 20.0
        elif hp >= 4:
            reserve = 10.0
        bid = min(bid, budget - reserve)
        if bid < 0:
            bid = min(budget, 0.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no one is alive, spend to ensure survival
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    yesterday_hps = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass
            try:
                yesterday_hps.append(float(prev.get('hp_after', o.get('hp', 0))))
            except Exception:
                pass

    # Baseline from supply: with 15-25 supply, typical number of winners is limited.
    # We want to be competitive but not match Cindy's consistent high bids.
    # Use a target fraction of DAILY_SALARY based on our HP.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Compute a conservative target using yesterday's distribution
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If someone overbid hard yesterday, we slightly undercut to win while saving budget.
        # Cindy's behavior tends to create a high ceiling; aim around 0.75 of max_prev or a floor.
        target = 0.75 * max_prev
    else:
        target = DAILY_SALARY * 0.55

    # Supply pressure adjustment: higher supply reduces need to overbid
    # Normalize supply to [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        s_norm = 0.5
    else:
        s_norm = (supply - MIN_SUPPLY) / denom
    # When supply is low, increase bids; when high, decrease.
    pressure = 1.0 + (0.25 * (0.5 - s_norm))  # low supply => >1

    # HP-based risk control
    if my_hp <= 2:
        hp_mult = 1.15
    elif my_hp <= 4:
        hp_mult = 1.05
    else:
        hp_mult = 0.95

    # Also react to no_water_days: if we are close to starvation, bid more.
    no_water_days = int(my_status['no_water_days'])
    if no_water_days >= 2:
        starvation_mult = 1.12
    elif no_water_days >= 1:
        starvation_mult = 1.06
    else:
        starvation_mult = 0.98

    # Final candidate bid
    candidate = target * pressure * hp_mult * starvation_mult

    # Keep within reasonable bounds: between 0.25 and 0.95 of DAILY_SALARY, but never above budget.
    lower = DAILY_SALARY * 0.25
    upper = DAILY_SALARY * 0.95
    bid = max(lower, min(upper, candidate))

    # Ensure we don't exceed budget
    if my_budget <= 0:
        return 0.0
    bid = min(bid, my_budget)

    # If budget is very tight, bid a smaller fraction rather than risking overspend
    if my_budget < DAILY_SALARY * 0.35:
        bid = min(bid, my_budget * 0.9)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 1.1)

    if day_context['supply'] < 18:
        return min(my_status['budget'], max(avg_prev * 1.05, 60.0))

    return min(my_status['budget'], max(avg_prev * 0.9, 45.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Determine base bid based on health
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9  # 126
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.7  # 98
    else:
        base_bid = DAILY_SALARY * 0.5  # 70

    # Adjust based on yesterday's highest bid
    yesterday_max = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid_val = float(prev['bid'])
            if bid_val > yesterday_max:
                yesterday_max = bid_val

    if yesterday_max > 0:
        # If we are desperate, try to outbid the max slightly
        if hp <= 2:
            bid = max(base_bid, yesterday_max + 2.0)
        elif hp <= 4:
            # moderate desire: outbid if we can afford
            bid = max(base_bid, yesterday_max + 1.0)
        else:
            # healthy: stay near base, but don't vastly overpay
            bid = max(base_bid, yesterday_max * 0.8)
    else:
        bid = base_bid

    # Ensure we don't exceed budget
    bid = min(bid, budget)
    # Ensure positive bid
    bid = max(bid, 0.01)

    return bid
